"""A project's dependencies, locked like doctrine's own tools: every package of the resolution at
an exact version, with the sha256 of every file the index publishes for it, so an install with
--require-hashes gets exactly what was reviewed on any platform."""

import re
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

LOCK_FILE = "requirements.lock"
HEADER = (
    "# This project's dependencies with every published file's sha256, installed with\n"
    "# --require-hashes. Generated by `doctrine deps lock` from pyproject.toml; don't edit it.\n"
)


@dataclass(frozen=True, order=True)
class Pin:
    name: str
    version: str

    def __str__(self) -> str:
        return f"{self.name}=={self.version}"


def normalised(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


def declared(pyproject: Mapping[str, Any]) -> list[str]:
    return [
        str(requirement) for requirement in pyproject.get("project", {}).get("dependencies", [])
    ]


def resolved_pins(report: Mapping[str, Any]) -> list[Pin]:
    """The packages in pip's installation report (`pip install --dry-run --report`)."""
    return sorted(
        Pin(normalised(entry["metadata"]["name"]), str(entry["metadata"]["version"]))
        for entry in report.get("install", [])
    )


def lock_entry(pin: Pin, hashes: Sequence[str]) -> str:
    if not hashes:
        raise ValueError(f"{pin} has no published files to hash")
    lines = [f"{pin} \\", *(f"    --hash=sha256:{digest} \\" for digest in sorted(hashes))]
    return "\n".join(lines).removesuffix(" \\")


def lock_text(hashes: Mapping[Pin, Sequence[str]]) -> str:
    entries = [lock_entry(pin, hashes[pin]) for pin in sorted(hashes)]
    return HEADER + "".join(entry + "\n" for entry in entries)
